# figS4.R
#
# Draws Supplementary Figure 4, the densities of the three lowest-copy
# compensated states and of the total population over the long run, and saves
# it as figures/FigS4.png. The long run is data from an old iteration of the
# model and is not regenerated by this code.
#
# One panel, drawn from the panel data frame FigS4. The frame holds one row
# per 24 h cycle of the run, the last hourly row of the cycle, with negative
# values set to zero and the total of the 20 states added (see
# 01_panel_data.R). Each line therefore joins one point per cycle and shows
# nothing of the course of a cycle.
#
# The frame is read from source_data/panel_data.rds, which 01_panel_data.R
# writes; if that file is absent, source 01_panel_data.R first. The working
# directory must be the repository root.
#
# Part of the code for "Unstable Heteroresistance as a Stepping Stone to Stable
# Resistance via Compensatory Mutations" (Berryhill and Andersson).
#
# Defines: PD, d, key, long, sf4_cols, sf4_lty and the figure figS4.

if (!exists("theme_hr")) source("R/figures/00_style.R")
suppressPackageStartupMessages(library(tidyr))
PD <- readRDS(PANEL_DATA_RDS)$data

# Long form with one row per time and series: `time` (h), `series` and
# `density` (cells per mL). The total population is added as a fourth series
# so that it is drawn by the same layer and has its own entry in the legend.
d   <- PD$FigS4
key <- c("R0C", "R1C", "R2C")
long <- pivot_longer(d[, c("time", key)], -time,
                     names_to = "series", values_to = "density")
long <- rbind(long,
              data.frame(time = d$time, series = "total", density = d$total))
long$series <- factor(long$series, levels = c("R0C", "R1C", "R2C", "total"))

# The three states are solid lines in three colours, and the total is a
# dashed line in the ink colour.
sf4_cols <- c(R0C = unname(HR_TOL["rose"]), R1C = unname(HR_TOL["indigo"]),
              R2C = unname(HR_TOL["teal"]), total = HR_PAL$ink)
sf4_lty  <- c(R0C = "solid", R1C = "solid", R2C = "solid", total = "22")

# The y axis is logarithmic and cannot show zero, so pmax(density, 1) draws
# densities below 1 cell per mL at 1. With the shipped data these are the
# zeros at the start of the run: R0C in the first nine cycles (to 215 h) and
# R1C in the first three (to 71 h). The last row of the series lies 7 h after
# the row before it, part-way through a cycle, and its densities are lower
# than at the end of a full cycle; this is the drop at the right-hand end of
# every line. The x axis is labelled in thousands of hours.
figS4 <- ggplot(long, aes(time, pmax(density, 1), colour = series,
                          linetype = series)) +
  geom_line(linewidth = 0.5) +
  scale_y_log10() +
  scale_x_continuous(labels = function(x) paste0(x / 1000, "k")) +
  scale_colour_manual(values = sf4_cols, name = NULL) +
  scale_linetype_manual(values = sf4_lty, name = NULL) +
  labs(x = "Time (h)", y = "Density (cells/mL)") +
  theme_hr()

save_fig(figS4, "FigS4", width_mm = WIDTH_1_5, height_mm = 78)

# The figure object is the last value of the script, which hands it to the
# caller and displays it when the script is run line by line.
figS4
